mapper.select:
select t.area,t.parking_type,t.parking_type parkingType,t.num,t.pa_id,t.pa_id paId,t.section_id,t.section_id
sectionId,t.owner_id,t.owner_id ownerId,t.owner_name,t.owner_name ownerName,t.car_id,t.car_id carId,t.car_num,t.car_num
carNum,t.start_time,t.start_time startTime,t.end_time,t.end_time endTime,t.ps_id,t.ps_id
psId,t.remark,t.status_cd,t.status_cd statusCd,t.state,t.community_id,t.community_id communityId,
pa.num paName,pa.num areaNum,s.section_num sectionNum,s.section_name sectionName
from parking_space t
left join parking_area pa on t.pa_id = pa.pa_id and pa.status_cd = '0'
left join parking_area_section s on t.section_id = s.section_id and s.status_cd = '0'
where 1 =1

    and t.area= #{area}


    and t.parking_type= #{parkingType}


    and t.num= #{num}


    and t.num in

        #{item}



    and t.pa_id= #{paId}


    and t.section_id= #{sectionId}


    and t.ps_id= #{psId}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.state in

        #{item}



    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update parking_space t set t.status_cd = #{statusCd}

    ,t.b_id = #{newBId}


    , t.area= #{area}


    , t.parking_type= #{parkingType}


    , t.num= #{num}


    , t.pa_id= #{paId}


    , t.section_id= #{sectionId}


    , t.owner_id= #{ownerId}


    , t.owner_name= #{ownerName}


    , t.car_id= #{carId}


    , t.car_num= #{carNum}


    , t.start_time= nullif(#{startTime}, '')


    , t.end_time= nullif(#{endTime}, '')


    , t.remark= #{remark}


    , t.state= #{state}


    , t.community_id= #{communityId}

where 1=1

    and t.ps_id= #{psId}

